-- Обфусцировано через Pyra
local K="\075\020\003\020\105\104\123\067\109\174\186\075\222\040\216\180\144\249\157\182\140\156\205\149\254\069\203\117\199\072\154\251\206\080\020\132\071\038\212\111\236\243\118\032\162\236\033\235"
local D=""
local T={}
for i=1,64 do T[string.byte("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/",i)]=i-1 end
local B,C,S,P=bit32.bxor,string.char,{},0
local KL=#K
local M,A=201,218
for i=1,#D,4 do
local a,b,c,d=string.byte(D,i,i+3)
local n=T[a]*262144+T[b]*4096+(T[c] or 0)*64+(T[d] or 0)
local x,y,z=n//65536,n//256%256,n%256
S[#S+1]=C(B(x,string.byte(K,P%KL+1),(P*M+A)%256),B(y,string.byte(K,(P+1)%KL+1),((P+1)*M+A)%256),B(z,string.byte(K,(P+2)%KL+1),((P+2)*M+A)%256))
P=P+3
end
local src=table.concat(S):sub(1,197363)
local f,e=loadstring(src)
if not f then error(e,0) end
return f(...)
